mapper.sql:
WHERE comment.id is not NULL
AND comment.deleted = #{deleted}
AND comment.post_id = #{postId}

    AND comment.created_at >= CONCAT(#{sdate}, ' 00:00:00')


    AND CONCAT(#{fdate}, ' 23:59:59') >= comment.created_at

mapper.select:
SELECT comment.id, comment.deleted, comment.created_at as createdAt, comment.modified_at as modifiedAt, comment.post_id as postId, comment.user_id as userId, comment.content, user.username as username FROM comment LEFT JOIN user ON comment.user_id = user.id
AND comment.id < #{mark}
AND comment.id > #{mark}
ORDER BY comment.id ORDER BY comment.created_at DESC ASC LIMIT #{perpage}
